.contact-icon{width:34px;height:34px;display:grid;place-items:center;border-radius:10px;background:var(--soft);color:var(--purple);font-size:16px;flex-shrink:0}.contact-item strong{display:block;font-size:12px;margin-bottom:3px}.muted{color:var(--muted)}.alert{border-radius:11px;font-size:13px}.sticky-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-top:18px;border-top:1px solid var(--line);margin-top:6px}.pill{display:inline-flex;align-items:center;gap:6px;border-radius:30px;background:#e8f8ef;color:#278755;font-size:11px;font-weight:700;padding:6px 10px}
